        n = len(data)
        mean = sum(data) / n
        variance = sum((x - mean) ** 2 for x in data) / n
        std = math.sqrt(variance)
        if std == 0:
            return 0
        skew = sum((x - mean) ** 3 for x in data) / n / (std ** 3)
        return skew

    @staticmethod
    def kurtosis(data):
        n = len(data)
        mean = sum(data) / n
        variance = sum((x - mean) ** 2 for x in data) / n
        if variance == 0:
            return float('nan')
        kurt = sum((x - mean) ** 4 for x in data) / n / (variance ** 2) - 3
        return kurt

    @staticmethod
    def pdf(data, mu, sigma):
        result = []
        for x in data:
            value = (1 / (sigma * math.sqrt(2 * math.pi))) * math.exp(-0.5 * ((x - mu) / sigma) ** 2)
