class EightPuzzle:
    """
    This class is an implementation of the classic 8-puzzle game, including methods for finding the blank tile, making moves, getting possible moves, and solving the puzzle using a breadth-first search algorithm.
    """

    def __init__(self, initial_state):
        self.initial_state = initial_state
        self.goal_state = [[1, 2, 3], [4, 5, 6], [7, 8, 0]]

    def find_blank(self, state):
        for i in range(3):
            for j in range(3):
                if state[i][j] == 0:
                    return (i, j)
        return None

    def move(self, state, direction):
        import copy
        blank = self.find_blank(state)
        if blank is None:
            return state
        i, j = blank
        new_state = copy.deepcopy(state)
        if direction == 'up':
            if i > 0:
                new_state[i][j], new_state[i-1][j] = new_state[i-1][j], new_state[i][j]
        elif direction == 'down':
            if i < 2:
                new_state[i][j], new_state[i+1][j] = new_state[i+1][j], new_state[i][j]
        elif direction == 'left':
            if j > 0:
                new_state[i][j], new_state[i][j-1] = new_state[i][j-1], new_state[i][j]
        elif direction == 'right':
            if j < 2:
                new_state[i][j], new_state[i][j+1] = new_state[i][j+1], new_state[i][j]
        return new_state

    def get_possible_moves(self, state):
        blank = self.find_blank(state)
        if blank is None:
            return []
        i, j = blank
        moves = []
        if i > 0:
            moves.append('up')
        if i < 2:
            moves.append('down')
        if j > 0:
            moves.append('left')
        if j < 2:
            moves.append('right')
        return moves

    def solve(self):
        import copy
        from collections import deque

        start = self.initial_state
        goal = self.goal_state

        # Check if blank exists in initial state
        if self.find_blank(start) is None:
            return None

        # Convert state to tuple for hashing
        def state_to_tuple(state):
            return tuple(tuple(row) for row in state)

        start_tuple = state_to_tuple(start)
        goal_tuple = state_to_tuple(goal)

        if start_tuple == goal_tuple:
            return []

        queue = deque()
        queue.append((start, []))
        visited = set()
        visited.add(start_tuple)

        while queue:
            current_state, path = queue.popleft()

            possible_moves = self.get_possible_moves(current_state)
            for direction in possible_moves:
                new_state = self.move(current_state, direction)
                new_tuple = state_to_tuple(new_state)

                if new_tuple == goal_tuple:
                    return path + [direction]

                if new_tuple not in visited:
                    visited.add(new_tuple)
                    queue.append((new_state, path + [direction]))

        return None

